  static List<Monument> byCategory(String category) =>
      all.where((m) => m.category == category).toList();

  static List<Monument> get featured => all.where((m) => m.isFeatured).toList();

  static Monument? byId(String id) =>
      all.cast<Monument?>().firstWhere((m) => m?.id == id, orElse: () => null);

  static List<Monument> search(String query) {
    final q = query.toLowerCase();
    return all
        .where((m) =>
            m.name.toLowerCase().contains(q) ||
            m.description.toLowerCase().contains(q) ||
            m.era.toLowerCase().contains(q) ||
            m.tags.any((t) => t.toLowerCase().contains(q)))
        .toList();
  }

